<script setup>
import { computed, onMounted, ref } from 'vue'
import Button from 'primevue/button'
import Card from 'primevue/card'
import Column from 'primevue/column'
import DataTable from 'primevue/datatable'
import Dialog from 'primevue/dialog'
import InputText from 'primevue/inputtext'
import Message from 'primevue/message'
import Select from 'primevue/select'
import Tag from 'primevue/tag'
import { rpc } from '../../services/supabase'

const rows=ref([]), teachers=ref([]), loading=ref(false), saving=ref(false), deleting=ref(false)
const message=ref(''), success=ref(''), search=ref(''), editorVisible=ref(false), deleteVisible=ref(false), editId=ref(null), deleteTarget=ref(null)
const gradeLevels=['ป.1','ป.2','ป.3','ป.4','ป.5','ป.6','ม.1','ม.2','ม.3'].map(v=>({label:v,value:v}))
const rooms=[1,2,3,4,5,6].map(v=>({label:`ห้อง ${v}`,value:String(v)}))
const statuses=[{label:'ใช้งาน',value:'active'},{label:'พักการใช้งาน',value:'inactive'}]
const form=ref(emptyForm())
function emptyAssignment(){return {gradeLevel:'ป.1',room:'1',teacherId:null,status:'active'}}
function emptyForm(){return {subjectCode:'',subjectName:'',status:'active',assignments:[emptyAssignment()]}}
const filtered=computed(()=>{const t=search.value.trim().toLowerCase();return rows.value.filter(r=>!t||[r.subjectCode,r.subjectName,...(r.assignments||[]).map(a=>a.homeroomTeacherName)].some(v=>String(v||'').toLowerCase().includes(t)))})
const assignmentCount=computed(()=>rows.value.reduce((sum,r)=>sum+(r.assignments?.length||0),0))
const teacherOptions=computed(()=>teachers.value.filter(t=>t.status==='active').map(t=>({label:`${t.teacherName} (${t.teacherCode})`,value:t.id})))
function teacherText(a){return a.teacherName || teachers.value.find(t=>t.id===a.teacherId)?.teacherName || '-'}
function addAssignment(){form.value.assignments.push(emptyAssignment())}
function removeAssignment(i){if(form.value.assignments.length>1)form.value.assignments.splice(i,1)}
function classText(r){return (r.assignments||[]).map(a=>`${a.gradeLevel}/${a.room} - ${teacherText(a)}`).join(', ')||'-'}
async function load(){loading.value=true;try{const [subjectRows,teacherRows]=await Promise.all([rpc('teacher_subjects_with_classes_list'),rpc('teacher_homeroom_list')]);rows.value=subjectRows||[];teachers.value=teacherRows||[]}catch(e){message.value=e.message||'โหลดข้อมูลไม่ได้'}finally{loading.value=false}}
function addItem(){editId.value=null;form.value=emptyForm();editorVisible.value=true}
function editItem(r){editId.value=r.id;form.value={subjectCode:r.subjectCode,subjectName:r.subjectName,status:r.status,assignments:(r.assignments?.length?r.assignments:[emptyAssignment()]).map(a=>({gradeLevel:a.gradeLevel,room:String(a.room),teacherId:a.teacherId||null,status:a.status||'active'}))};editorVisible.value=true}
async function saveItem(){const p={id:editId.value,subjectCode:form.value.subjectCode.trim(),subjectName:form.value.subjectName.trim(),status:form.value.status,assignments:form.value.assignments};if(!p.subjectCode)return message.value='กรุณากรอกรหัสวิชา';if(!p.subjectName)return message.value='กรุณากรอกชื่อวิชา';const keys=p.assignments.map(a=>`${a.gradeLevel}/${a.room}`);if(new Set(keys).size!==keys.length)return message.value='มีชั้น / ห้องซ้ำในรายการ';saving.value=true;try{await rpc('teacher_subject_save_multi',{p_payload:p});editorVisible.value=false;success.value='บันทึกวิชาและชั้นเรียนแล้ว';await load()}catch(e){message.value=e.message||'บันทึกไม่ได้'}finally{saving.value=false}}
function askDelete(r){deleteTarget.value=r;deleteVisible.value=true}
async function deleteItem(){deleting.value=true;try{await rpc('teacher_subject_delete_multi',{p_subject_id:deleteTarget.value.id});deleteVisible.value=false;await load()}catch(e){message.value=e.message||'ลบไม่ได้'}finally{deleting.value=false}}
onMounted(load)
</script>
<template><div class="subject-page">
<section class="hero"><div><span class="kicker"><i class="pi pi-book"></i> SUBJECT & CLASS MANAGEMENT</span><h1>วิชาและชั้นเรียน</h1><p>สร้างวิชาครั้งเดียว แล้วกำหนดได้หลายชั้น หลายห้อง</p></div><Button label="เพิ่มวิชา" icon="pi pi-plus" class="add" @click="addItem"/></section>
<Message v-if="message" severity="error" closable @close="message=''">{{message}}</Message><Message v-if="success" severity="success" closable @close="success=''">{{success}}</Message>
<section class="summary"><article><span class="blue"><i class="pi pi-book"></i></span><div><small>รายวิชา</small><b>{{rows.length}}</b><em>วิชา</em></div></article><article><span class="green"><i class="pi pi-building"></i></span><div><small>การเปิดสอน</small><b>{{assignmentCount}}</b><em>ชั้น / ห้อง</em></div></article></section>
<Card class="registry"><template #content><div class="heading"><div><span class="heading-icon"><i class="pi pi-bookmark"></i></span><div><h2>ทะเบียนรายวิชา</h2><p>หนึ่งวิชาสามารถเปิดสอนได้หลายชั้นและหลายห้อง</p></div></div><Button label="รีเฟรช" icon="pi pi-refresh" outlined :loading="loading" @click="load"/></div><div class="tools"><div class="search"><i class="pi pi-search"></i><InputText v-model="search" placeholder="ค้นหารหัสวิชา ชื่อวิชา หรือครู..."/></div></div><DataTable :value="filtered" striped-rows responsive-layout="scroll" class="table"><Column field="subjectCode" header="รหัสวิชา"/><Column field="subjectName" header="ชื่อวิชา"/><Column header="ชั้น / ห้องที่เปิดสอน"><template #body="{data}">{{classText(data)}}</template></Column><Column header="จำนวน"><template #body="{data}"><Tag severity="info" :value="`${data.assignments?.length||0} ห้อง`"/></template></Column><Column header="จัดการ"><template #body="{data}"><div class="actions"><Button label="แก้ไข" icon="pi pi-pencil" outlined size="small" @click="editItem(data)"/><Button label="ลบ" icon="pi pi-trash" text severity="danger" size="small" @click="askDelete(data)"/></div></template></Column></DataTable></template></Card>
<Dialog v-model:visible="editorVisible" modal :header="editId?'แก้ไขวิชา':'เพิ่มวิชาและกำหนดชั้นเรียน'" :style="{width:'min(48rem,96vw)'}"><form class="form" @submit.prevent="saveItem"><div class="grid"><label><span>รหัสวิชา *</span><InputText v-model="form.subjectCode" placeholder="เช่น THAI" fluid/></label><label><span>ชื่อวิชา *</span><InputText v-model="form.subjectName" placeholder="เช่น ภาษาไทย" fluid/></label></div><label><span>สถานะวิชา</span><Select v-model="form.status" :options="statuses" option-label="label" option-value="value" fluid/></label><div class="assign-head"><div><b>ชั้น / ห้องที่เปิดสอน</b><small>เพิ่มได้เรื่อย ๆ พร้อมเลือกครูผู้สอน โดยไม่ต้องสร้างวิชาใหม่</small></div><Button type="button" label="เพิ่มชั้น / ห้อง" icon="pi pi-plus" outlined @click="addAssignment"/></div><div class="assignment" v-for="(a,i) in form.assignments" :key="i"><Select v-model="a.gradeLevel" :options="gradeLevels" option-label="label" option-value="value"/><Select v-model="a.room" :options="rooms" option-label="label" option-value="value"/><Select v-model="a.teacherId" :options="teacherOptions" option-label="label" option-value="value" placeholder="เลือกครูผู้สอน" filter show-clear/><Button type="button" icon="pi pi-trash" severity="danger" text :disabled="form.assignments.length===1" @click="removeAssignment(i)"/></div><div class="dialog-actions"><Button type="button" label="ยกเลิก" text severity="secondary" @click="editorVisible=false"/><Button type="submit" label="บันทึก" icon="pi pi-save" :loading="saving"/></div></form></Dialog>
<Dialog v-model:visible="deleteVisible" modal header="ยืนยันการลบ"><p>ลบวิชา <b>{{deleteTarget?.subjectName}}</b> และรายการชั้น / ห้องทั้งหมด?</p><div class="dialog-actions"><Button label="ยกเลิก" text @click="deleteVisible=false"/><Button label="ลบ" severity="danger" :loading="deleting" @click="deleteItem"/></div></Dialog>
</div></template>
<style scoped>
.subject-page{--navy:#102b52;--blue:#167df5;--green:#16b884;--line:#dce7f2;--muted:#71839d;display:grid;gap:18px}.hero{min-height:165px;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:26px 30px;border:1px solid var(--line);border-radius:20px;background:linear-gradient(110deg,#fff,#f2f8ff 60%,#effbf6);box-shadow:0 14px 36px rgba(24,57,94,.07)}.kicker{display:inline-flex;align-items:center;gap:7px;padding:6px 10px;border-radius:999px;color:var(--blue);background:#e7f2ff;font-size:9px;font-weight:800;letter-spacing:.08em}.hero h1{margin:12px 0 5px;color:var(--navy);font-size:34px}.hero p{margin:0;color:var(--muted)}.add{min-width:200px;height:50px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.summary article{display:flex;align-items:center;gap:14px;min-height:108px;padding:18px;border:1px solid #e1eaf3;border-radius:16px;background:#fff}.summary article>span{width:52px;height:52px;display:grid;place-items:center;border-radius:50%;font-size:20px}.summary small,.summary b,.summary em{display:block}.summary small{color:#425d79;font-size:11px;font-weight:700}.summary b{color:var(--navy);font-size:28px}.summary em{color:var(--muted);font-size:9px;font-style:normal}.blue{color:var(--blue);background:#e1efff}.green{color:#0ca575;background:#ddf8ed}.purple{color:#7c4dff;background:#eee7ff}.registry{border:1px solid var(--line);border-radius:18px;overflow:hidden}.heading{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:18px}.heading>div{display:flex;align-items:center;gap:12px}.heading-icon{width:50px;height:50px;display:grid;place-items:center;border-radius:50%;color:#7c4dff;background:#eee7ff}.heading h2{margin:0;color:var(--navy)}.heading p{margin:3px 0 0;color:var(--muted);font-size:11px}.tools{display:grid;grid-template-columns:1fr 190px 180px;gap:10px;margin-bottom:14px}.search{position:relative}.search>i{position:absolute;left:13px;top:50%;transform:translateY(-50%);z-index:2;color:#68809a}.search :deep(.p-inputtext){width:100%;padding-left:38px}.table{border:1px solid var(--line);border-radius:12px;overflow:hidden}.table :deep(.p-datatable-thead>tr>th){background:#eef4f9;color:#344f6d;font-size:11px}.actions{display:flex;gap:4px}.form{display:grid;gap:15px}.form label{display:grid;gap:7px;color:#294766;font-size:12px;font-weight:700}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.dialog-actions{display:flex;justify-content:flex-end;gap:8px}@media(max-width:800px){.summary{grid-template-columns:1fr}.tools,.grid{grid-template-columns:1fr}.heading,.hero{align-items:flex-start;flex-direction:column}.add{width:100%}}

.assign-head{display:flex;justify-content:space-between;align-items:center;gap:12px;padding-top:5px}.assign-head small,.assign-head b{display:block}.assign-head small{margin-top:3px;color:#71839d;font-size:10px}.assignment{display:grid;grid-template-columns:130px 130px minmax(220px,1fr) auto;gap:9px;align-items:center;padding:10px;border:1px solid #dce7f2;border-radius:11px;background:#f8fbfe}.tools{grid-template-columns:1fr}.summary{grid-template-columns:repeat(2,1fr)}@media(max-width:700px){.assignment{grid-template-columns:1fr}.assign-head{align-items:stretch;flex-direction:column}}
</style>
